/**
 * MarketHub fork: the one font family every piece of chart text is set in.
 *
 * TradingView's Lightweight Charts stack, so the axes, tags, crosshair chips
 * and legends read the way a TradingView chart does: Trebuchet MS on Windows,
 * the system UI face on macOS, Roboto or Ubuntu on Linux. Upstream set each
 * renderer's text in `system-ui` (Segoe UI on Windows) on its own.
 */
export const CHART_FONT_FAMILY = "-apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu, sans-serif";
